class Solution:
    def findLatestStep(self, arr: List[int], m: int) -> int:
        n = len(arr)
        if m == n:
            return n
        length = [0] * (n + 2)
        res = -1
        for step, pos in enumerate(arr, 1):
            left = length[pos - 1]
            right = length[pos + 1]
            new_len = left + right + 1
            length[pos - left] = new_len
            length[pos + right] = new_len
            if left == m or right == m:
                res = step - 1
        return res

class Solution:
    def stoneGameV(self, stoneValue: List[int]) -> int:
        n = len(stoneValue)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + stoneValue[i]
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(i, j):
            if i == j:
                return 0
            res = 0
            for k in range(i, j):
                left_sum = prefix[k + 1] - prefix[i]
                right_sum = prefix[j + 1] - prefix[k + 1]
                if left_sum <= right_sum:
                    res = max(res, left_sum + dp(i, k))
                if right_sum <= left_sum:
                    res = max(res, right_sum + dp(k + 1, j))
            return res
        return dp(0, n - 1)

