class Solution:
    def minDays(self, grid: List[List[int]]) -> int:
        def count_islands(g):
            seen = set()
            count = 0
            for i in range(len(g)):
                for j in range(len(g[0])):
                    if g[i][j] == 1 and (i, j) not in seen:
                        count += 1
                        stack = [(i, j)]
                        seen.add((i, j))
                        while stack:
                            x, y = stack.pop()
                            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                                nx, ny = x+dx, y+dy
                                if 0<=nx<len(g) and 0<=ny<len(g[0]) and g[nx][ny]==1 and (nx,ny) not in seen:
                                    seen.add((nx, ny))
                                    stack.append((nx, ny))
            return count
        if count_islands(grid) != 1:
            return 0
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == 1:
                    grid[i][j] = 0
                    if count_islands(grid) != 1:
                        return 1
                    grid[i][j] = 1
        return 2

class Solution:
    def numOfWays(self, nums: List[int]) -> int:
        from math import comb
        MOD = 10**9 + 7
        def solve(arr):
            if len(arr) <= 2:
                return 1
            root = arr[0]
            left = [x for x in arr if x < root]
            right = [x for x in arr if x > root]
            return comb(len(left) + len(right), len(left)) * solve(left) % MOD * solve(right) % MOD
        return (solve(nums) - 1) % MOD

class SparseVector:
    def __init__(self, nums: List[int]):
        self.nonzero = {i: v for i, v in enumerate(nums) if v != 0}
    def dotProduct(self, vec: 'SparseVector') -> int:
        a, b = self.nonzero, vec.nonzero
        if len(a) > len(b):
            a, b = b, a
        return sum(v * b[i] for i, v in a.items() if i in b)

