class Solution:
    def numWays(self, s: str) -> int:
        MOD = 10**9 + 7
        ones = s.count('1')
        n = len(s)
        if ones == 0:
            return (n - 1) * (n - 2) // 2 % MOD
        if ones % 3 != 0:
            return 0
        target = ones // 3
        count = 0
        gap1 = gap2 = 0
        for c in s:
            if c == '1':
                count += 1
            if count == target:
                gap1 += 1
            elif count == 2 * target:
                gap2 += 1
        return gap1 * gap2 % MOD

class Solution:
    def findLengthOfShortestSubarray(self, arr: List[int]) -> int:
        n = len(arr)
        left = 0
        while left < n - 1 and arr[left] <= arr[left + 1]:
            left += 1
        if left == n - 1:
            return 0
        right = n - 1
        while right > 0 and arr[right - 1] <= arr[right]:
            right -= 1
        res = min(n - left - 1, right)
        i, j = 0, right
        while i <= left and j < n:
            if arr[i] <= arr[j]:
                res = min(res, j - i - 1)
                i += 1
            else:
                j += 1
        return res

class Solution:
    def countRoutes(self, locations: List[int], start: int, finish: int, fuel: int) -> int:
        MOD = 10**9 + 7
        from functools import lru_cache
        n = len(locations)
        @lru_cache(maxsize=None)
        def dp(city, remaining):
            if remaining < 0:
                return 0
            res = 1 if city == finish else 0
            for next_city in range(n):
                if next_city != city:
                    cost = abs(locations[city] - locations[next_city])
                    if cost <= remaining:
                        res = (res + dp(next_city, remaining - cost)) % MOD
            return res
        return dp(start, fuel)

