class Solution:
    def numTriplets(self, nums1: List[int], nums2: List[int]) -> int:
        from collections import Counter
        def count_pairs(arr, target):
            cnt = Counter()
            res = 0
            for num in arr:
                if target % num == 0:
                    res += cnt[target // num]
                cnt[num] += 1
            return res
        result = 0
