        for x in nums2:
            result += count_pairs(nums1, x * x)
        return result

class Solution:
    def maxNumEdgesToRemove(self, n: int, edges: List[List[int]]) -> int:
        class UF:
            def __init__(self, n):
                self.parent = list(range(n + 1))
                self.rank = [0] * (n + 1)
                self.components = n
            def find(self, x):
                while self.parent[x] != x:
                    self.parent[x] = self.parent[self.parent[x]]
                    x = self.parent[x]
                return x
            def union(self, x, y):
                px, py = self.find(x), self.find(y)
                if px == py: return False
                if self.rank[px] < self.rank[py]: px, py = py, px
                self.parent[py] = px
                if self.rank[px] == self.rank[py]: self.rank[px] += 1
                self.components -= 1
                return True
        alice, bob = UF(n), UF(n)
        removed = 0
        for t, u, v in edges:
            if t == 3:
                a = alice.union(u, v)
                b = bob.union(u, v)
                if not a and not b: removed += 1
        for t, u, v in edges:
            if t == 1:
                if not alice.union(u, v): removed += 1
            elif t == 2:
                if not bob.union(u, v): removed += 1
        if alice.components != 1 or bob.components != 1: return -1
        return removed

