class ThroneInheritance:
    def __init__(self, kingName: str):
        self.king = kingName
        self.children = {}
        self.dead = set()
    def birth(self, parentName: str, childName: str):
        if parentName not in self.children:
            self.children[parentName] = []
        self.children[parentName].append(childName)
    def death(self, name: str):
        self.dead.add(name)
    def getInheritanceOrder(self):
        order = []
        def dfs(name):
            if name not in self.dead:
                order.append(name)
            for child in self.children.get(name, []):
                dfs(child)
        dfs(self.king)
        return order

class Solution:
    def maximumRequests(self, n: int, requests: List[List[int]]) -> int:
        m = len(requests)
        res = 0
        for mask in range(1 << m):
            if bin(mask).count('1') <= res:
                continue
            balance = [0] * n
            for i in range(m):
                if mask & (1 << i):
                    balance[requests[i][0]] -= 1
                    balance[requests[i][1]] += 1
            if all(b == 0 for b in balance):
                res = bin(mask).count('1')
        return res

class Solution:
    def findNearestRightNode(self, root, u):
        from collections import deque
        queue = deque([root])
        while queue:
            size = len(queue)
            for i in range(size):
                node = queue.popleft()
                if node == u:
                    return queue[0] if i < size - 1 else None
                if node.left: queue.append(node.left)
                if node.right: queue.append(node.right)
        return None

