class Solution:
    def isEvenOddTree(self, root) -> bool:
        from collections import deque
        queue = deque([root])
        level = 0
        while queue:
            size = len(queue)
            prev = float('-inf') if level % 2 == 0 else float('inf')
            for _ in range(size):
                node = queue.popleft()
                if level % 2 == 0:
                    if node.val % 2 == 0 or node.val <= prev:
                        return False
                else:
                    if node.val % 2 == 1 or node.val >= prev:
                        return False
                prev = node.val
                if node.left: queue.append(node.left)
                if node.right: queue.append(node.right)
            level += 1
        return True

class Solution:
    def visiblePoints(self, points: List[List[int]], angle: int, location: List[int]) -> int:
        import math
        same = 0
        angles = []
        for x, y in points:
            if x == location[0] and y == location[1]:
                same += 1
            else:
                angles.append(math.atan2(y - location[1], x - location[0]) * 180 / math.pi)
        angles.sort()
        angles = angles + [a + 360 for a in angles]
        res = 0
        left = 0
        for right in range(len(angles)):
            while angles[right] - angles[left] > angle:
                left += 1
            res = max(res, right - left + 1)
        return res + same

