class Solution:
    def checkEquivalence(self, root1, root2) -> bool:
        from collections import Counter
        def count(node):
            if not node:
                return Counter()
            if node.val != '+':
                return Counter([node.val])
            return count(node.left) + count(node.right)
        return count(root1) == count(root2)

